-- Retail's Haranir druid forms (tools/races/haranir_druid_forms.py; the models are in WHE-common). The model rows
-- copy the Night Elf forms' size and sounds; each display is one of retail's colours (texture types 11 and 12).
-- The same rows are in F-098 and F-099, so either one works alone.

DELETE FROM `creaturemodeldata` WHERE `id` IN (@DruidCatHaranirModel, @DruidBearHaranirModel, @DruidTravelHaranirModel, @DruidAquaticHaranirModel, @DruidMoonkinHaranirModel, @DruidTreeHaranirModel);
SELECT @DruidCatHaranirModel, `flags`, 'Creature\\druidcatharanir\\druidcatharanir.m2', `size_class`, `model_scale`, `blood_id`, `footprint_texture_id`, `footprint_texture_length`, `footprint_texture_width`, `footprint_particle_scale`, `foley_material_id`, `footstep_shake_size`, `death_thud_shake_size`, `sound_data`, `collision_width`, `collision_height`, `mount_height`, `geo_box_min_x`, `geo_box_min_y`, `geo_box_min_z`, `geo_box_max_x`, `geo_box_max_y`, `geo_box_max_z`, `world_effect_scale`, `attached_effect_scale`, `missile_collision_radius`, `missile_collision_push`, `missile_collision_raise` FROM `creaturemodeldata` WHERE `id` = (SELECT `model_id` FROM `creaturedisplayinfo` WHERE `id` = 892) /* the Night Elf cat form's model */
UNION ALL
