SELECT @DruidAquaticHaranirModel, `flags`, 'Creature\\druidaquaticharanir\\druidaquaticharanir.m2', `size_class`, `model_scale`, `blood_id`, `footprint_texture_id`, `footprint_texture_length`, `footprint_texture_width`, `footprint_particle_scale`, `foley_material_id`, `footstep_shake_size`, `death_thud_shake_size`, `sound_data`, `collision_width`, `collision_height`, `mount_height`, `geo_box_min_x`, `geo_box_min_y`, `geo_box_min_z`, `geo_box_max_x`, `geo_box_max_y`, `geo_box_max_z`, `world_effect_scale`, `attached_effect_scale`, `missile_collision_radius`, `missile_collision_push`, `missile_collision_raise` FROM `creaturemodeldata` WHERE `id` = (SELECT `model_id` FROM `creaturedisplayinfo` WHERE `id` = 2428) /* the Night Elf aquatic form's model */
