DELETE FROM `creaturedisplayinfo` WHERE `id` IN (@DruidCatHaranir0Display, @DruidCatHaranir1Display, @DruidCatHaranir2Display, @DruidCatHaranir3Display, @DruidCatHaranir4Display, @DruidBearHaranir0Display, @DruidBearHaranir1Display, @DruidBearHaranir2Display, @DruidBearHaranir3Display, @DruidBearHaranir4Display, @DruidTravelHaranir0Display, @DruidTravelHaranir1Display, @DruidTravelHaranir2Display, @DruidTravelHaranir3Display, @DruidTravelHaranir4Display, @DruidAquaticHaranir0Display, @DruidAquaticHaranir1Display, @DruidAquaticHaranir2Display, @DruidAquaticHaranir3Display, @DruidAquaticHaranir4Display, @DruidMoonkinHaranir0Display, @DruidMoonkinHaranir1Display, @DruidMoonkinHaranir2Display, @DruidMoonkinHaranir3Display, @DruidMoonkinHaranir4Display, @DruidTreeHaranir0Display);
